    echo "╔═══════════════════════════════════════════════════════════════╗"
    echo "║            Pre-push Hook Unit Tests                          ║"
    echo "╚═══════════════════════════════════════════════════════════════╝"

    test_run_with_timeout_exit_codes
    test_changelog_variable_capture
    test_run_with_timeout_spaces
    test_skip_regex_parity
    test_bash32_compatibility
    test_resolve_push_branch
    test_rejects_repo_config_drift
    test_probe_fixture_git_environment_scrub
    test_vitest_git_environment_scrub
    test_resolve_pre_push_jobs
    test_shared_load_backoff_fixture
    test_captured_stage_exit_status
    test_security_stage_rejects_path_stub
    test_stages_do_not_inherit_worktree_git_dir
    test_scrub_keeps_locators_without_rediscovery
    test_targeted_mode_selection
    test_targeted_mode_fallbacks
    test_selector_picks_matching_tests
    test_slot_governor_queue_and_reclaim

    # Summary
    echo ""
    echo "═══════════════════════════════════════════════════════════════"
    echo "                        TEST SUMMARY"
    echo "═══════════════════════════════════════════════════════════════"
    echo -e "  Passed:  ${GREEN}${TESTS_PASSED}${NC}"
    echo -e "  Failed:  ${RED}${TESTS_FAILED}${NC}"
    echo ""

    if [[ $TESTS_FAILED -gt 0 ]]; then
        echo -e "${RED}FAIL${NC}: Some tests failed"
        exit 1
    else
        echo -e "${GREEN}PASS${NC}: All tests passed"
        exit 0
    fi
}

main "$@"
